using System; using System.Collections.Generic; using System.IO; using System.Linq; using System.Net.Http; using System.Net.Http.Json; using System.Text.Json; using System.Threading.Tasks; using Avalonia; using Avalonia.Controls; using Avalonia.Layout; using Avalonia.Media; using Avalonia.Input;
namespace ZodiAI.Linux;
public sealed class MainWindow:Window {
 const string Api="https://zodi-ai-core.vercel.app/api/chat"; static readonly HttpClient Http=new(){Timeout=TimeSpan.FromSeconds(70)};
 readonly string store=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"zodi-ai","conversations.json"); readonly List<Conversation> items=new();
 readonly ListBox history=new(); readonly StackPanel messages=new(){Spacing=12}; readonly TextBox input=new(){Watermark="Écris ton message à Zodi…",AcceptsReturn=true,MinHeight=48}; readonly TextBlock title=new(){Text="Zodi AI",FontSize=20,FontWeight=FontWeight.SemiBold}; readonly TextBlock status=new(){Text="Assistant personnel · Internet requis",Foreground=Brush("#9AA8BE"),FontSize=12}; readonly Button send=new(){Content="Envoyer",MinWidth=100,Height=44}; Conversation? active; bool switching;
 static SolidColorBrush Brush(string c)=>new(Color.Parse(c));
 public MainWindow(){Title="Zodi AI";Width=1120;Height=760;MinWidth=760;MinHeight=540;Background=Brush("#10131B");try{if(File.Exists(store))items.AddRange(JsonSerializer.Deserialize<List<Conversation>>(File.ReadAllText(store))??new());}catch{}
 history.SelectionChanged+=(_,_)=>{if(!switching&&history.SelectedItem is Conversation c)Select(c);};send.Click+=async(_,_)=>await Send();input.KeyDown+=async(_,e)=>{if(e.Key==Key.Enter&&!e.KeyModifiers.HasFlag(KeyModifiers.Shift)){e.Handled=true;await Send();}};
 var create=new Button{Content="＋ Nouvelle conversation",Height=42};create.Click+=(_,_)=>Create();var rename=new Button{Content="Renommer"};rename.Click+=async(_,_)=>await Rename();var delete=new Button{Content="Supprimer"};delete.Click+=async(_,_)=>await Delete();
 var side=new StackPanel{Spacing=12,Margin=new Thickness(16),Width=250};side.Children.Add(new TextBlock{Text="✦  Zodi AI",FontSize=23,FontWeight=FontWeight.Bold,Foreground=Brush("#F4F6FC"),Margin=new Thickness(4,8)});side.Children.Add(create);side.Children.Add(new TextBlock{Text="TES CONVERSATIONS",Foreground=Brush("#9AA8BE"),FontSize=11,Margin=new Thickness(4,10,4,0)});side.Children.Add(history);side.Children.Add(new TextBlock{Text="Historique enregistré sur cet ordinateur",Foreground=Brush("#8994A9"),FontSize=11,TextWrapping=TextWrapping.Wrap});
 var head=new Grid{ColumnDefinitions=new ColumnDefinitions("*,Auto")};var labels=new StackPanel{Spacing=5,Margin=new Thickness(22,18)};labels.Children.Add(title);labels.Children.Add(status);head.Children.Add(labels);var actions=new StackPanel{Orientation=Orientation.Horizontal,Spacing=8,HorizontalAlignment=HorizontalAlignment.Right};actions.Children.Add(rename);actions.Children.Add(delete);Grid.SetColumn(actions,1);head.Children.Add(actions);
 var scroll=new ScrollViewer{Content=messages,Padding=new Thickness(24)};var composer=new Grid{ColumnDefinitions=new ColumnDefinitions("*,Auto"),Margin=new Thickness(18,12)};composer.Children.Add(input);Grid.SetColumn(send,1);send.Margin=new Thickness(10,0,0,0);composer.Children.Add(send);
 var right=new Grid{RowDefinitions=new RowDefinitions("Auto,*,Auto")};right.Children.Add(head);Grid.SetRow(scroll,1);right.Children.Add(scroll);Grid.SetRow(composer,2);right.Children.Add(composer);var root=new Grid{ColumnDefinitions=new ColumnDefinitions("280,*")};root.Children.Add(new Border{Background=Brush("#171B25"),Child=side});Grid.SetColumn(right,1);root.Children.Add(right);Content=root;
 if(items.Count==0)Create();else Select(items[0]); }
 void Save(){try{Directory.CreateDirectory(Path.GetDirectoryName(store)!);File.WriteAllText(store,JsonSerializer.Serialize(items));}catch(Exception e){status.Text="Sauvegarde impossible : "+e.Message;}}
 void Refresh(){switching=true;history.ItemsSource=null;history.ItemsSource=items;history.SelectedItem=active;switching=false;}
 void Create(){var c=new Conversation();c.Messages.Add(new Message("assistant","Salut ! Je suis Zodi. Que veux-tu faire aujourd'hui ?"));items.Insert(0,c);active=c;Refresh();Render();Save();}
 void Select(Conversation c){active=c;title.Text=c.Title;Render();}
 void Render(){messages.Children.Clear();if(active==null)return;title.Text=active.Title;foreach(var m in active.Messages)Bubble(m.Content,m.Role=="user");}
 void Bubble(string text,bool user){var b=new Border{Background=Brush(user?"#354F86":"#1B2230"),CornerRadius=new CornerRadius(14),Padding=new Thickness(15,11),MaxWidth=720,HorizontalAlignment=user?HorizontalAlignment.Right:HorizontalAlignment.Left};b.Child=new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,Foreground=Brush("#FFFFFF"),FontSize=14};messages.Children.Add(b);}
 async Task<string?> Prompt(string caption,string value){var box=new TextBox{Text=value};var ok=new Button{Content="Enregistrer",HorizontalAlignment=HorizontalAlignment.Right};var panel=new StackPanel{Margin=new Thickness(18),Spacing=12};panel.Children.Add(box);panel.Children.Add(ok);var w=new Window{Title=caption,Width=380,Height=170,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=panel};ok.Click+=(_,_)=>w.Close(box.Text);return await w.ShowDialog<string?>(this);}
 async Task Rename(){if(active==null)return;var v=await Prompt("Renommer la conversation",active.Title);if(!string.IsNullOrWhiteSpace(v)){active.Title=v.Trim();title.Text=active.Title;Refresh();Save();}}
 async Task Delete(){if(active==null)return;var w=new Window{Title="Supprimer la conversation ?",Width=360,Height=150,WindowStartupLocation=WindowStartupLocation.CenterOwner};var p=new StackPanel{Margin=new Thickness(18),Spacing=12};p.Children.Add(new TextBlock{Text=$"Supprimer « {active.Title} » de cet ordinateur ?"});var b=new Button{Content="Supprimer",HorizontalAlignment=HorizontalAlignment.Right};p.Children.Add(b);w.Content=p;b.Click+=(_,_)=>w.Close(true);if(await w.ShowDialog<bool>(this)){items.Remove(active);active=null;if(items.Count==0){Create();return;}active=items[0];Refresh();Render();Save();}}
 async Task Send(){if(active==null||string.IsNullOrWhiteSpace(input.Text)||!send.IsEnabled)return;var c=active;var text=input.Text.Trim();input.Text="";var prior=c.Messages.ToArray();c.Messages.Add(new Message("user",text));if(c.Title=="Nouvelle conversation")c.Title=text.Length>42?text[..39]+"…":text;title.Text=c.Title;Refresh();Bubble(text,true);Save();send.IsEnabled=false;status.Text="Zodi réfléchit…";try{using var r=await Http.PostAsJsonAsync(Api,new{message=text,history=prior});var body=await r.Content.ReadAsStringAsync();if(!r.IsSuccessStatusCode)throw new Exception($"HTTP {(int)r.StatusCode}: {body}");using var j=JsonDocument.Parse(body);var answer=j.RootElement.TryGetProperty("reply",out var a)?a.GetString():null;if(string.IsNullOrWhiteSpace(answer))throw new Exception("Réponse vide du serveur.");c.Messages.Add(new Message("assistant",answer));if(active==c)Bubble(answer,false);status.Text="Réponse reçue · Zodi AI";Save();}catch(Exception e){var err="Impossible de joindre Zodi AI. Vérifie Internet puis réessaie.\n"+e.Message;c.Messages.Add(new Message("assistant",err));if(active==c)Bubble(err,false);status.Text="Connexion indisponible";Save();}finally{send.IsEnabled=true;}}
 public sealed class Conversation{public string Id{get;set;}=Guid.NewGuid().ToString();public string Title{get;set;}="Nouvelle conversation";public List<Message> Messages{get;set;}=new();public override string ToString()=>Title;} public sealed record Message(string Role,string Content);
}